import React from "react";
import {
  createBrowserRouter,
  RouterProvider,
  Outlet,
} from "react-router-dom";

// Common Components
import Navbar from "./components/Navbar";
import Footer from "./components/Footer";
import Notification from "./components/Notification";

// Public Pages
import Home from "./pages/Home";
import DonationRequest from "./pages/DonationRequest";
import DonorScheduling from "./pages/DonorScheduling";
import PatientBloodRequest from "./pages/PatientBloodRequest";
import Profile from "./pages/Profile";
import About from "./pages/About";
import Contact from "./pages/Contact";

// Admin Pages
import AdminNavbar from "./admin/AdminNavbar";
import BloodStock from "./admin/BloodStock";

// Root Layout
function RootLayout() {
  return (
    <>
      <Notification />
      <Outlet />
    </>
  );
}

// Public Website Layout
function PublicLayout() {
  return (
    <>
      <Navbar />
      <main>
        <Outlet />
      </main>
      <Footer />
    </>
  );
}

// Admin Panel Layout
function AdminLayout() {
  return (
    <>
      <AdminNavbar />
      <main>
        <Outlet />
      </main>
      <Footer />
    </>
  );
}

// Router Configuration
const router = createBrowserRouter([
  {
    element: <RootLayout />,
    children: [
      // Public Website Routes
      {
        element: <PublicLayout />,
        children: [
          { path: "/", element: <Home /> },
          {
            path: "/donation-request",
            element: <DonationRequest />,
          },
          {
            path: "/donor-scheduling",
            element: <DonorScheduling />,
          },
          {
            path: "/patient-blood-request",
            element: <PatientBloodRequest />,
          },
          { path: "/profile", element: <Profile /> },
          { path: "/about", element: <About /> },
          { path: "/contact", element: <Contact /> },
        ],
      },

      // Admin Panel Routes
      {
        path: "/admin",
        element: <AdminLayout />,
        children: [
          {
            path: "blood-stock",
            element: <BloodStock />,
          },
        ],
      },

      // Default Route
      {
        path: "*",
        element: <Home />,
      },
    ],
  },
]);

function App() {
  return <RouterProvider router={router} />;
}

export default App;
